DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM public.housing_units WHERE seq IS NULL) THEN
    RAISE EXCEPTION 'seq 를 못 채운 세대 행 % — 덤프 뒤 새 행이 생겼다(목록을 다시 뜬다)', (SELECT count(*) FROM public.housing_units WHERE seq IS NULL);
  END IF;
END $$;

ALTER TABLE public.housing_units ALTER COLUMN seq SET NOT NULL;
ALTER TABLE public.housing_units ALTER COLUMN seq ADD GENERATED BY DEFAULT AS IDENTITY;
SELECT setval(pg_get_serial_sequence('public.housing_units', 'seq'), (SELECT max(seq) FROM public.housing_units));

COMMENT ON COLUMN public.housing_units.seq IS '들어간 순서(화면 같은 보증금 안 순서) — 2026-10-07 이전 행은 (created_at, 2026-10-06 정기 덤프 행 순서)로 채움 · 새 행은 identity.';
